mapper.select:
select distinct oj_course.name,oj_course.resource_id,oj_course.difficulty,oj_course_category.name as category_name, oj_course.create_user_id as create_user,ifnull(lesson.count,0) as lesson_count,ifnull(learned_lessons.count,0) as heat, ifnull(report.count,0) as finish_report_count from oj_course left join oj_course_category on oj_course.category_id = oj_course_category.resource_id left join (select count(course_id) as count,course_id from oj_lesson_record group by course_id) learned_lessons on learned_lessons.course_id = oj_course.resource_id left join (select count(course_id) as count,course_id from oj_course_lesson group by course_id) lesson on lesson.course_id = oj_course.resource_id left join (select count(oj_course_lesson.course_id) as count, oj_course_lesson.course_id from oj_note left join oj_course_lesson on oj_course_lesson.resource_id = oj_note.business_id where note_type =2 and business_type = 2 group by oj_course_lesson.course_id) report on report.course_id = oj_course.resource_id
and oj_course.resource_id in
#{courseId}
and oj_course.`difficulty` = #{courseContext.difficulty}
and oj_course.`category_id` in
#{direction}
and oj_course.`name` like #{pattern}
and oj_course.`public` = #{isPublic}

select distinct oj_course_lesson.resource_id,oj_course_lesson.name,oj_course_lesson.type,oj_course_lesson.difficulty, ifnull(learned_lessons.count,0) as heat,ifnull(practice_afterclass.count,0) as practice_count,ifnull(report.count,0) as finish_report_count from oj_course_lesson left join (select count(oj_lesson_record.lesson_id) as count ,oj_lesson_record.lesson_id from oj_lesson_record group by oj_lesson_record.lesson_id ) as learned_lessons on learned_lessons.lesson_id = oj_course_lesson.resource_id left join (select count(oj_lesson_paper_evaluate.lesson_id) as count ,oj_lesson_paper_evaluate.lesson_id from oj_lesson_paper_evaluate group by oj_lesson_paper_evaluate.lesson_id ) as practice_afterclass on practice_afterclass.lesson_id = oj_course_lesson.resource_id left join (select count(oj_note.business_id) as count ,oj_note.business_id from oj_note where business_type = 2 and note_type = 2 group by oj_note.business_id ) as report on report.business_id = oj_course_lesson.resource_id where course_id = #{courseId}
and oj_course_lesson.`type` = #{type}
and oj_course_lesson.`name` like #{search}

select lesson_id, record from oj_lesson_paper_evaluate

    where lesson_id in

        #{lessonId}

select distinct oj_lesson_record.id, oj_lesson_record.user_id as submit_user_id,report.score as score, report.evaluate_time as marking_time,report.update_time as report_update_time, (case when report.update_time is null then false else true end) as is_report,practice.record from oj_lesson_record left join (select * from oj_lesson_paper_evaluate where lesson_id = #{lessonId}) practice on practice.submit_user_id = oj_lesson_record.user_id left join (select oj_note_evaluate.score ,oj_note.user_id as user,oj_note_evaluate.evaluate_time as evaluate_time ,oj_note.update_time as update_time from oj_note left join oj_note_evaluate on oj_note_evaluate.note_id = oj_note.resource_id where oj_note.business_id = #{lessonId} and oj_note.note_type = 2 ) report on oj_lesson_record.user_id = report.user where oj_lesson_record.lesson_id = #{lessonId}
and user_id in
#{userId}

select oj_lesson_paper_evaluate.submit_user_id as submit_user_id,record from oj_lesson_paper_evaluate
where oj_lesson_paper_evaluate.lesson_id = #{lessonId}

    and oj_lesson_paper_evaluate.submit_user_id in

        #{userId}

select oj_note.user_id as submit_user_id,oj_note.update_time as report_update_time, oj_note_evaluate.evaluate_time as marking_time,ifnull(oj_note_evaluate.score,0) as score from oj_note left join oj_note_evaluate on oj_note_evaluate.note_id = oj_note.resource_id where oj_note.business_id = #{lessonId} and oj_note.business_type = 2 and oj_note.note_type = 2
and oj_note.user_id in
#{userId}
